// Rule 2 of setup's managed-file check: whether a file's first lines carry a generator's notice,
// a statement that the file ITSELF is generated or managed by another tool. Only such a notice counts. A person's own
// rule that mentions generated files, editing or "this file" is not one, because refusing a
// person's own file is the frustration this rule must not cause in ordinary use. The check is a
// best-effort reading of free text, and it errs both ways. Both errors are cheap: a person's own
// file refused by mistake costs one paste, because the refusal names the line and print-block; a
// generated file that is missed loses the block at its tool's next run, which doctor reports.
// The table in `generated.test.ts` is the rule: every alternative below has a row only it matches.
//
// The rule, in full:
// - Examples are never notices: text in a fenced code block, a block quote or a list item (with
//   the indented lines after it) is skipped before any phrase is tried.
// - Spaces and dashes are made plain first: any run of spaces is one space, any dash a hyphen.
// - A notice opens a comment (TOML's whole-line `#` comment, Markdown's HTML comment), a line of
//   Markdown text after heading and emphasis marks, or, in the first line of text and in a heading
//   that names a file, a piece after a bracket, a dash, a colon or a sentence's end. It is one of:
//   "(code) (auto-)generated by|from|with|using", "(auto-)generated file", "(auto-)generated"
//   alone, "managed by", "<tool> managed" alone, "@generated" alone, or a bare "do not
//   edit|modify" (optionally "this file", "manually", "directly", "by hand") that ends there.
// - A sentence that names the file counts where a sentence starts, in a comment or in text:
//   "this file is|was|will be (auto-)generated, regenerated, managed, synced or overwritten",
//   "changes (made) to this file will be lost|overwritten", "this is a|an (auto-)generated file".
// - Only the first 20 lines are read, and of each line and each comment its first 1,000
//   characters, so a long line near the top (a pasted blob) costs no more than a short one. Text
//   that reaches that bound is never a notice: a cut can leave a phrase that only looks whole.
import { parseToml } from "../config/toml.ts";
import { ScanError, tomlComments } from "../config/scan.ts";

/** How many lines a notice may start in. */
export const NOTICE_LINES = 20;
/** How much of each line, and of each comment, is read: a notice is short and stands first. */
export const NOTICE_CHARS = 1000;

const GEN = String.raw`(?:auto[- ]?|automatically )?generated`;
/** What may close a phrase: emphasis marks, then the end or a punctuation mark. */
const ENDS = String.raw`(?=[*_]*\s*(?:$|[.!:;,(-]))`;
/** A bare "do not edit" before a colon introduces what not to edit, so a colon does not end it. */
const ENDS_BARE = String.raw`(?=[*_]*\s*(?:$|[.!;,(-]))`;

/** The phrases that open a generator's notice. */
const STARTS = new RegExp(
  "^(?:" +
    [
      String.raw`(?:code )?${GEN} (?:by|from|with|using)\b`,
      String.raw`${GEN} file${ENDS}`,
      String.raw`${GEN}${ENDS}`,
      String.raw`managed by\b`,
      String.raw`[\w.-]{1,64} managed${ENDS}`,
      String.raw`@generated\s*$`,
      String.raw`do not (?:edit|modify)(?: this file)?(?: (?:manually|directly|by hand))?${ENDS_BARE}`,
    ].join("|") +
    ")",
  "iu",
);
/** A sentence that names the file itself as generated or managed. */
const ABOUT_ITSELF = new RegExp(
  "^(?:" +
    [
      String.raw`this file (?:is|was|will be) (?:${GEN}|regenerated|managed|synced|overwritten)\b`,
      String.raw`changes (?:made )?to this file will be (?:lost|overwritten)\b`,
      String.raw`this is an? ${GEN} file\b`,
    ].join("|") +
    ")",
  "iu",
);
/** Where a sentence starts inside a line. */
const SENTENCE = /[.!?:] /u;
/** Where a notice may start inside a title. */
const TITLE_BREAK = /\(| - |[.!?:] /u;
/** A heading that names a file, such as `## AGENTS.md - generated by ...`: read as a title. */
const FILE_HEADING = /^#{1,6} [\w./-]+\.\w+(?=[ (:]|$)/u;

/** A block quote or list item line: an example, never a notice. */
const EXAMPLE = /^\s*(?:>|(?:[-*+]|\d+[.)])(?:\s|$))/u;
/** A fence that opens or closes a code block. */
const FENCE = /^ {0,3}(`{3,}|~{3,})/u;

/** Any run of spaces becomes one space, any dash a hyphen. */
const plain = (text: string): string =>
  text
    .replace(/[\u2010-\u2015\u2212]/gu, "-")
    .replace(/\s+/gu, " ")
    .trim();
/** The text after heading and emphasis marks. */
const bare = (text: string): string => text.replace(/^[\s#*_]*/u, "");

const aboutItself = (text: string): boolean =>
  text.split(SENTENCE).some((piece) => ABOUT_ITSELF.test(bare(piece)));

const opens = (text: string): boolean => STARTS.test(bare(text)) || aboutItself(text);

function inText(line: string, first: boolean): boolean {
  const text = plain(line);
  if (opens(text)) return true;
  if (!first && !FILE_HEADING.test(text)) return false;
  return text
    .split(TITLE_BREAK)
    .slice(1)
    .some((piece) => STARTS.test(bare(piece)));
}

/** The first lines, each cut at the bound, and whether it was cut. */
function firstLines(text: string): { text: string; cut: boolean }[] {
  return text
    .split("\n", NOTICE_LINES)
    .map((line) => line.replace(/\r$/u, ""))
    .map((line) => ({ text: line.slice(0, NOTICE_CHARS), cut: line.length > NOTICE_CHARS }));
}

/** The 0-based lines among the first ones that are a whole-line TOML comment, or undefined. */
function tomlCommentLines(text: string): Set<number> | undefined {
  // The scanner runs only on text the parser accepted (its depth bound guards the scanner).
  if (!parseToml(text).ok) return undefined;
  let offsets: readonly number[];
  try {
    offsets = tomlComments(text);
  } catch (error) {
    if (error instanceof ScanError) return undefined;
    throw error;
  }
  const lines = new Set<number>();
  let line = 0;
  let start = 0;
  for (const at of offsets) {
    for (let next = text.indexOf("\n", start); next !== -1 && next < at;) {
      line += 1;
      start = next + 1;
      next = text.indexOf("\n", start);
    }
    if (line >= NOTICE_LINES) break;
    if (text.slice(start, at).trim() === "") lines.add(line);
  }
  return lines;
}

function tomlNotice(text: string): number | undefined {
  const comments = tomlCommentLines(text);
  const at = firstLines(text).findIndex((line, i) => {
    const trimmed = line.text.trim();
    if (line.cut || !trimmed.startsWith("#")) return false;
    // A text the parser refuses is read line by line: the file is refused either way.
    if (comments !== undefined && !comments.has(i)) return false;
    return opens(plain(trimmed.replace(/^#+/u, "")));
  });
  return at === -1 ? undefined : at + 1;
}

function markdownNotice(text: string): number | undefined {
  let comment: { start: number; text: string; cut: boolean } | undefined;
  let fence: string | undefined;
  let example = false;
  let first = true;
  const judge = (c: { text: string; cut: boolean }): boolean =>
    !c.cut && c.text.length < NOTICE_CHARS && opens(plain(c.text));
  for (const [i, line] of firstLines(text).entries()) {
    if (comment === undefined) {
      // Examples: a fenced code block, a block quote, a list item and its indented lines.
      if (fence !== undefined) {
        // A closing fence: the same mark, at least as long, and nothing after it.
        const close = FENCE.exec(line.text)?.[1] ?? "";
        const same = close.startsWith(fence[0] ?? "") && close.length >= fence.length;
        if (same && line.text.trim() === close) fence = undefined;
        continue;
      }
      const open = FENCE.exec(line.text);
      if (open !== null) {
        fence = open[1];
        first = false;
        continue;
      }
      if (line.text.trim() === "") continue;
      if (EXAMPLE.test(line.text) || (example && /^\s/u.test(line.text))) {
        example = true;
        first = false;
        continue;
      }
      example = false;
    }
    let rest = line.text;
    let words = "";
    while (rest !== "") {
      if (comment !== undefined) {
        const close = rest.indexOf("-->");
        const part = close === -1 ? rest : rest.slice(0, close);
        comment.text = `${comment.text} ${part}`.slice(0, NOTICE_CHARS);
        if (close === -1) break;
        if (judge(comment)) return comment.start;
        comment = undefined;
        rest = rest.slice(close + 3);
        words += " ";
      } else {
        const open = rest.indexOf("<!--");
        if (open === -1) {
          words += rest;
          break;
        }
        words += `${rest.slice(0, open)} `;
        comment = { start: i + 1, text: "", cut: false };
        rest = rest.slice(open + 4);
      }
    }
    if (comment !== undefined && line.cut) comment.cut = true;
    if (words.trim() === "") continue;
    if (!line.cut && inText(words, first)) return i + 1;
    first = false;
  }
  return comment !== undefined && judge(comment) ? comment.start : undefined;
}

/**
 * The 1-based line a generator's notice starts on in the file's first 20 lines, or undefined for
 * none. TOML's notice is a whole-line `#` comment; Markdown's is an HTML comment or the text
 * itself (above). The text is without a byte order mark.
 */
export const generatorNotice = (text: string, format: "toml" | "markdown"): number | undefined =>
  format === "toml" ? tomlNotice(text) : markdownNotice(text);

/** Whether the file carries a generator's notice. */
export const markedAsGenerated = (text: string, format: "toml" | "markdown"): boolean =>
  generatorNotice(text, format) !== undefined;
